const mat=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.78,...extra});
const white=mat('#efeee7'),wood=mat('#b7905e'),black=mat('#303a3c'),metal=mat('#abb8b9',{metalness:.65,roughness:.3}),leaf=mat('#54765c');
