 floor(){const room=this.room;const floor=this.state.flooring;box(this.root,0,-.16,0,room.w+.19,.24,room.d+.19,mat('#c2c8c2'),.05);const tile=floor==='tile';const pw=tile?.5:.17,pd=tile?.65:1.22;const cols=Math.ceil(room.w/pw),rows=Math.ceil(room.d/pd);const mesh=new THREE.InstancedMesh(baseGeo,mat('#ffffff'),cols*(rows+1));let index=0;const matrix=new THREE.Matrix4(),color=new THREE.Color();const base={oak:'#c69e6d',light:'#dcd0b3',dark:'#795d48',tile:'#637078'}[floor];for(let i=0;i<cols;i++){const x=-room.w/2+Math.min(pw/2,room.w/2)+i*pw;const sw=Math.min(pw,room.w-i*pw);for(let j=0;j<=rows;j++){const start=-room.d/2+j*pd-(i%3)*(tile?0:pd/3);const end=Math.min(start+pd,room.d/2);const front=Math.max(start,-room.d/2);if(end<=front)continue;matrix.compose(new THREE.Vector3(x-(pw-sw)/2,-.022,(front+end)/2),new THREE.Quaternion(),new THREE.Vector3(sw-.006,.055,end-front-.008));mesh.setMatrixAt(index,matrix);color.set(base);color.multiplyScalar(.9+((i*71+j*13)%17)/100);mesh.setColorAt(index,color);index++;}}mesh.count=index;mesh.receiveShadow=true;this.root.add(mesh);}
