   if(edge==='n')g.position.z=-r.d/2;if(edge==='s'){g.position.z=r.d/2;g.rotation.y=Math.PI;}if(edge==='w'){g.position.x=-r.w/2;g.rotation.y=Math.PI/2;}if(edge==='e'){g.position.x=r.w/2;g.rotation.y=-Math.PI/2;}
   // Mirror offsets on south/west where local X runs against world coordinates.
